void dvb_usb_disconnect(struct usb_interface *intf) {
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int i;

    if (!d)
        return;

    for (i = 0; i < d->props.num_adapters; i++) {
        if (d->props.adapter[i].exit)
            d->props.adapter[i].exit(d);
    }

    dvb_usbv2_exit(d);

    printk(KERN_INFO "DVB/USB: Disconnected device %s\n", d->name);

    kfree(d->name);
    kfree(d);
}

