void dvb_usb_disconnect(struct usb_interface *intf)
{
    struct dvb_usb_device *d;
    struct usb_device *udev;
    int n = intf->altsetting->desc.bInterfaceNumber;

    d = usb_get_intfdata(intf);
    if (!d)
        return;

    udev = interface_to_usbdev(intf);

    if (d->props.disconnect) {
        d->props.disconnect(d);
    }

    dvb_usbv2_exit(d);

    usb_set_intfdata(intf, NULL);
    dev_info(&intf->dev, "DVB USB: interface %d has been disconnected\n", n);
    kfree(d);
}

void dvb_usb_disconnect(struct usb_interface *intf)
{
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int i;

    for (i = 0; i < intf->cur_altsetting->desc.bNumEndpoints; i++) {
        usb_kill_anchored_urb(&d->usb.urb);
    }

    if (d->props.exit)
        d->props.exit(d);

    dvb_usbv2_exit(d);
    dev_info(&intf->dev, "dvb_usb: success\n");
    kfree(d->name);
    usb_set_intfdata(intf, NULL);
}
